import fs from 'node:fs';import vm from 'node:vm';import path from 'node:path';import {fileURLToPath} from 'node:url';
const root=path.dirname(fileURLToPath(import.meta.url));
let html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const css=[
 fs.readFileSync(path.join(root,'style.css'),'utf8'),
 fs.readFileSync(path.join(root,'focus-v2.css'),'utf8'),
 fs.readFileSync(path.join(root,'focus-polish.css'),'utf8'),
 fs.readFileSync(path.join(root,'original-config.css'),'utf8'),
 fs.readFileSync(path.join(root,'focus-v3.css'),'utf8'),
 fs.readFileSync(path.join(root,'focus-v3-hotfix.css'),'utf8'),
 fs.readFileSync(path.join(root,'focus-home-restore.css'),'utf8')
].join('\n');
const read=name=>fs.readFileSync(path.join(root,name),'utf8');
const engine=read('engine.mjs').replace(/export /g,'');
const app=read('app.js').replace(/^import .*?;\n/,'');
const originalAssetFiles=fs.readdirSync(root).filter(name=>/^original-asset-.*\.js$/.test(name)).sort();
const originalAssets=[read('original-assets-base.js'),...originalAssetFiles.map(read)].join('\n');
const fruitAddon=read('fruit-addon.js'),fruitFixes=read('fruit-fixes.js'),failedFruitAddon=read('failed-fruit-addon.js'),originalUiAddon=read('original-ui-addon.js'),focusV3=read('focus-v3.js'),focusV3Hotfix=read('focus-v3-hotfix.js');
html=html.replace('<link rel="stylesheet" href="style.css" />',()=>`<meta name="robots" content="noindex,nofollow,noarchive"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; media-src data: blob:; connect-src 'none'; form-action 'none'; base-uri 'none'"><style>${css}</style>`);
html=html.replace('<script type="module" src="app.js"></script>',()=>`<script>window.FOCUS_INITIAL=__FOCUS_STATE__;</script><script type="module">${originalAssets}\n${engine}\n${app}\n${fruitAddon}\n${fruitFixes}\n${failedFruitAddon}\n${originalUiAddon}\n${focusV3}\n${focusV3Hotfix}</script>`);
for(const file of ['tomato.png','tomato-small.png','app-icon.png','pear.svg','pear-hd.svg','fail_tomato1.svg','fail_tomato2.svg','fail_tomato3.svg','home-pause.svg','home-continue.svg','home-stop.svg']){
 const ext=path.extname(file).slice(1),mime=ext==='svg'?'image/svg+xml':'image/png';
 const source=path.join(root,'assets',file);if(!fs.existsSync(source))continue;
 html=html.replaceAll(`assets/${file}`,`data:${mime};base64,`+fs.readFileSync(source).toString('base64'));
}
for(const [index,match] of [...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/g)].entries())new vm.Script(match[1],{filename:`focus-bundle-${index}.js`});
if(/assets\/(?:tomato-interval|tomato-data|tomato-config|fail-tomato-data|pause\.png|continue\.png|stop\.png|sound(?:-off)?\.png|back-data\.png|prev-data\.png|next-data(?:-disabled)?\.png|tag-arrow\.png|more\.png|picker-select\.png|pear-hd\.svg)/.test(html))throw new Error('Unresolved FocusPomo asset path remains in private bundle');
for(const required of ['FP_ORIGINAL_ASSET_DATA.fail1','FP_ORIGINAL_ASSET_DATA.fail2','FP_ORIGINAL_ASSET_DATA.fail3','FP_ORIGINAL_ASSET_DATA.failedData','FP_ORIGINAL_ASSET_DATA.pause','FP_ORIGINAL_ASSET_DATA.sound','--fp-original-background','FP5_HD_TOMATO','FP6_forceHdFruitRoles','desktop-focus-decor','Restore the Focus home/start surface on ALL device classes'])if(!html.includes(required))throw new Error(`Missing recovered asset/config: ${required}`);
const destination=path.join(root,'../../supabase/functions/owner-focus/bundle.ts');
fs.writeFileSync(destination,'// Generated by backend/focuspomo/build-bundle.mjs\nexport const appHTML = '+JSON.stringify(html)+';\n');
fs.copyFileSync(path.join(root,'engine.mjs'),path.join(root,'../../supabase/functions/owner-focus/engine.mjs'));
console.log(`Private bundle: ${Buffer.byteLength(html)} bytes; recovered asset scripts: ${originalAssetFiles.length}`);
